def is_simple_power(x, n):
    # Handle special cases for n = 0, 1, -1
    if n == 0:
        return x == 0
    if n == 1:
        return x == 1
    if n == -1:
        return x == 1 or x == -1

    # For other n, iterate over possible exponents
    power = 1  # n^0
    exp = 0
    while True:
        if power == x:
            return True

        # Stop if we know no future power can equal x
        if n > 1 and power > x:
            break
        if n < -1 and exp > 0 and abs(power) > abs(x):
            break

        # Compute next power n^(exp+1)
        exp += 1
        power = n ** exp

    return False
