def encrypt(s):
    """
    Encrypts a string by rotating the alphabet by 4 places.
    Example: encrypt('hi') returns 'lm'
    """
    result = []
    for char in s:
        if 'a' <= char <= 'z':
            # Shift by 4, wrapping around the alphabet
            shifted = chr((ord(char) - ord('a') + 4) % 26 + ord('a'))
            result.append(shifted)
        else:
            result.append(char)  # keep non-alphabetic characters unchanged
    return ''.join(result)

def rounded_avg(n, m):
    if n > m:
        return -1
    # Compute sum of integers from n to m using arithmetic series formula
    count = m - n + 1
    total = (n + m) * count // 2
    avg = total / count
    rounded = round(avg)  # Python's round uses banker's rounding (round half to even)
    return bin(rounded)

